insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q1',1,'Systemic Safety','assignment','medium','single','What does the “Systemic Safety” strategy in the Disaster Risk Equation primarily aim to achieve?','["Improve a specific model’s ability to withstand external hazards", "Identify and avoid hazards through real-time monitoring", "Reduce the likelihood of conflict and overall systemic risks in the environment", "Align an agent’s goals with human values"]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Risk Part 3 [34:02-34:55] - We can look at the risk equation as a "systemic” safety, which in turn can generally reduce the risks.','Review Systemic Safety.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q2',1,'Deceptive Alignment','assignment','medium','single','In the context of “Deceptive Alignment,” what is the primary concern regarding model behavior?','["The model appears to follow safety guidelines during training but pursues different goals after deployment", "The model cannot understand human language due to environmental differences", "The model accidentally deletes critical memory during deployment", "The model’s safeguards are easily bypassed by simple user prompts"]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Risk Part 4 [23:34-24:23] - Deceptive alignment is shown by the example as the model appearing to grab the ball/asnwer a specific way but later doesn’t.','Review Deceptive Alignment.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q3',1,'Proxy Gaming','assignment','medium','single','According to the lecture, why is “proxy gaming” considered a failure mode in AI systems?','["Agents over-optimize fault metrics, producing outcomes misaligned with true human values", "AI systems consume excessive computational resources unnecessarily", "AI systems are used to cheat in video games", "It results from hardware failure during large-scale simulations"]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Risk Part 4 [20:26-22:17] - Future artificial agents could over-optimize and game faulty proxies, which could mean systems aggressively pursue goals and create a world that is distinct from what humans value.','Review Proxy Gaming.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q4',1,'Power Seeking','assignment','medium','single','According to the lecture, why might AI systems develop an “instrumental incentive” to seek power?','["They are explicitly programmed to dominate humans", "Power and resources help them pursue their goals more effectively", "It is a biological byproduct of the neural network design", "They imitate human power-seeking behavior from training data"]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Risk Part 4 [9:51-11:50] - By default, suitably strategic and intelligent agents, engaging in suitable types of planning, will have instrumental incentives to gain and maintain various types of power, since this power will help them pursue their objectives more effectively.','Review Power Seeking.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q5',1,'Treacherous Turn','assignment','medium','single','What does the term “Treacherous Turns” refer to in AI safety?','["Failures caused by biased training data", "A system behaving differently once sufficiently capable", "Intentional misuse of AI by malicious humans", "Over-optimization of proxy objectives"]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Risk Part 4 [22:18-23:34] - AI could behave differently once it has the ability to do so.','Review Treacherous Turn.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q6',1,'Swiss Cheese Model','assignment','medium','single','According to the “Swiss cheese model”, which statement best describes effective safety design?','["Rely on a single, highly robust safety mechanism", "Implement safety measures randomly across the system", "Use multiple layers of defense so that individual weaknesses are compensated by others", "Eliminate safety measures if the AI system is well-designed"]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Risk Part 3 [8:18-10:48] - The Swiss Cheese model shows how technical factors can improve organizational safety. Multiple layers of defense compensate for each other’s individual weaknesses, leading to a low overall level of risk.','Review Swiss Cheese Model.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q7',1,'Military AI Risks','assignment','medium','multi','According to the lecture, what are the potential “double-edged sword” risks associated with AI in military applications? (Select all that apply.)','["Autonomous weapons targeting humans with high precision", "Complete elimination of the need for human strategic decision-making", "Lowering the barriers to large-scale violence", "Autonomous retaliation systems increasing the risk of rapid escalation"]'::jsonb,'[0, 2, 3]'::jsonb,NULL,0.0,'AI Risk Part 3 [1:02-2:55] - Low-cost automated weapons, such as drone swarms outfitted with explosives, could autonomously hunt human targets with high precision, performing lethal operations for both militaries and terrorist groups and lowering the barriers to large-scale violence.','Review Military AI Risks.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q8',1,'Speculative Hazards','assignment','medium','multi','Which of the following are considered speculative hazards of AI? (Select all that apply.)','["Eroded Epistemics", "Enfeeblement", "Deceptive Alignment", "Hardware Degradation"]'::jsonb,'[0, 1, 2]'::jsonb,NULL,0.0,'Slide 146 in the week’s lecture notes lists speculative hazards and failure modes.','Review Speculative Hazards.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q9',1,'Risk Mitigation','assignment','medium','multi','The Disaster Risk Equation can be mitigated by (Select all that apply.):','["Improving agents’ robustness to withstand hazards", "Identifying and mitigating hazards before they cause harm", "Increasing the number of parameters to drown out errors", "Reducing the severity of inherent model vulnerabilities"]'::jsonb,'[0, 1, 3]'::jsonb,NULL,0.0,'AI Risk Part 3 [29:45-34:02] - Each component has one way to mitigate/reduce it. Vulnerability: Robustness; Hazard Exposure: Monitoring; Hazard: Alignment.','Review Risk Mitigation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q10',1,'Enfeeblement','assignment','medium','single','Which risk refers to humans voluntarily ceding control of socio-economic functions to AI to keep up with the automated world?','["Eroded Epistemics", "Deceptive Alignment", "Proxy Gaming", "Enfeeblement"]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Risk Part 3 [2:57-3:44] - As AIs automate increasingly many tasks, the economy may become largely run by AIs. Eventually, this could lead to human enfeeblement and dependence on AIs for basic needs.','Review Enfeeblement.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q11',1,'Risk Equation','assignment','medium','single','In the risk decomposition framework, which combination of factors would result in the HIGHEST risk from an AI system?','["High vulnerability, high hazard exposure, high hazard severity.", "Low vulnerability, high hazard exposure, low hazard severity.", "Low vulnerability, low hazard exposure, high hazard severity.", "High vulnerability, low hazard exposure, high hazard severity."]'::jsonb,'[0]'::jsonb,NULL,0.0,'Slide 107 in the week’s lecture notes shows the risk decomposition equation as a multiplicative (non-linear) equation. Increasing one increases the overall risk.','Review Risk Equation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w1_q12',1,'AI Race','assignment','medium','single','According to the lecture, which of the following about the AI race is true?','["AI systems naturally become safer as they grow more powerful.", "The AI race reduces the need for regulation and monitoring.", "It ensures faster AI development that guarantees equal benefits for all nations.", "AI competition may push to speed up development while giving up oversight."]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Risk Part 3 [0:20-1:01] - Competition could push nations and corporations to rush AI development, relinquishing control to these systems.','Review AI Race.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q1',2,'Black Swans','assignment','medium','single','What are “Black Swans”?','["Frequent events with predictable and minor impacts.", "Outlier events that often have extreme and unpredictable impacts.", "Known risks that are intentionally ignored during model training.", "Events that follow a thin-tailed distribution and have negligible consequences."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Robustness Part 1 [3:36-5:12] - Black swans are events that are outliers, lying outside typical expectations, and often carry extreme impact.','Review Black Swans.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q2',2,'Known Unknowns','assignment','medium','multi','Which of the following is considered a “Known Unknown”? (Select all that apply.)','["Recollection", "Closed-ended Questions", "Meta-ignorance", "Conscious Ignorance", "Open-ended Exploration", "Self-analysis"]'::jsonb,'[1, 3]'::jsonb,NULL,0.0,'Robustness Part 1 [19:20-22:05] - “Known Unknowns” are things we are aware of but don’t understand such as known classic risks/conscious ignorance or closed-ended questions.','Review Known Unknowns.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q3',2,'Covariate Shift','assignment','medium','single','Which type of distribution shift occurs when the input distribution 𝑃(𝑥) changes between training and testing but 𝑃(𝑦|𝑥) remains constant?','["Concept shift", "Normalized shift", "Covariate shift", "Prior probability shift"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Robustness Part 2 [23:00-24:53] - P(x) changes between train and test, but p(y|x) does not change in covariate shift.','Review Covariate Shift.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q4',2,'Transferability','assignment','medium','single','What is “transferability” in the context of adversarial attacks?','["The ability to move a model from a secure state to a vulnerable state.", "The phenomenon where adversarial examples crafted for one model also fool another model.", "Converting a black-box model into a white-box model.", "The process of retraining a model on adversarial attacks."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Lecture 8 and 9 Lecture Notes (Slide 70): Adversarial examples crafted for one model, can be used to attack other models is known as transferability.','Review Transferability.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q5',2,'Adversarial Training','assignment','medium','single','According to the lecture, what is a common trade-off when using Adversarial Training to improve robustness?','["It requires a significantly larger dataset than normal training.", "It can significantly reduce the accuracy on clean examples.", "It only works for simple binary classifiers.", "It requires a low-variance dataset to function effectively."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Lecture 8 and 9 Lecture Notes (Slide 78): Currently, adversarial training can reduce accuracy on clean examples by 10%+.','Review Adversarial Training.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q6',2,'Human Ratings','assignment','medium','multi','Which of the following are challenges associated with direct human ratings when modeling preferences? (Select all that apply.)','["Human-in-the-loop evaluation is expensive and time-consuming.", "Direct ratings require white-box access to the model.", "Human ratings are always completely objective and free from annotator bias.", "Human judgments are noisy and miscalibrated."]'::jsonb,'[0, 3]'::jsonb,NULL,0.0,'RLHF [8:39-13:31] - There are two problems with human ratings: human-in-the-loop is expensive and human judgments are noisy and miscalibrated.','Review Human Ratings.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q7',2,'DPO','assignment','medium','single','What does Direct Preference Optimization (DPO) represent in the RLHF framework?','["RLHF without the reward model", "RLHF without human feedback", "RLHF without reinforcement learning", "RLHF without policy optimization"]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Alignment [4:54-6:35] - RLHF – Reward model = Direct Preference Optimization (DPO)','Review DPO.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q8',2,'RLHF','assignment','medium','single','What is the first step of the RLHF pipeline?','["Collecting comparison data and training a reward model.", "Optimizing a policy against the reward model using reinforcement learning.", "Collecting demonstration data and training a supervised policy.", "Performing external white-box auditing of the pretrained model."]'::jsonb,'[2]'::jsonb,NULL,0.0,'RLHF [3:57-6:38] - The first step in the RLHF pipeline is to collect demonstration data and train a supervised model.','Review RLHF.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q9',2,'Black-box Auditing','assignment','medium','single','Why is black-box access insufficient for rigorous AI audits?','["It is too expensive for external auditors.", "It does not allow for human-in-the-loop feedback.", "It prevents the use of reinforcement learning.", "It only allows auditors to query the system and observe outputs."]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Alignment [24:28-25:13] - Auditors can only query the system and observe its output.','Review Black-box Auditing.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q10',2,'KL Penalty','assignment','medium','single','According to the lecture, what does the Kullback–Leibler (KL) divergence penalty prevent in RLHF?','["The reward model from becoming too complex", "The policy model from diverging too far from the initial pretrained model", "Human evaluators from providing biased feedback", "The model from over-generalizing"]'::jsonb,'[1]'::jsonb,NULL,0.0,'RLHF [14:31-16:35] - Kullback–Leibler (KL) divergence is the penalty which prevents us from diverging too far from the pretrained model.','Review KL Penalty.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q11',2,'Mediocristan vs Extremistan','assignment','medium','multi','Which of the following is true? (Select all that apply.)','["Extremistan has thin tails while Medicristan has long tails.", "Extremistan is determined by many small events.", "Mediocristan is the tyranny of the collective.", "Extremistan’s impact is potentially scalable."]'::jsonb,'[2, 3]'::jsonb,NULL,0.0,'Robustness Part 1 [17:22-19:19]','Review Mediocristan vs Extremistan.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w2_q12',2,'Long-tail Distribution','assignment','medium','single','Identify the equations that can lead to a long-tailed distribution.','["Idea * student * resources * time", "Idea * student + resources * time", "Idea + student + resource + time", "Idea - student * resource - time"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Robustness Part 1 [15:17-17:21] - Research output = Ideas X Time X Students X Resources','Review Long-tail Distribution.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q1',3,'Exact vs Approximate Unlearning','assignment','medium','single','Match the unlearning method to their corresponding concept. 1) Exact unlearning i) Unlearned model and retrained model are distributionally close 2) Unlearning via Differential Privacy ii) The forget set is clearly defined 3) Example Unlearning iii) The forget set is not clearly defined 4) Concept Unlearning iv) Unlearned model and retrained model are distributionally identical','["1 -> i, 2-> iv, 3-> iii, 4-> ii", "1 -> i, 2-> iv, 3-> ii, 4-> iii", "1 -> iv, 2-> i, 3-> iii, 4-> ii", "1 -> iv, 2-> i, 3-> ii, 4-> iii"]'::jsonb,'[3]'::jsonb,NULL,0.0,'Answers are found throughout the Unlearning and Approximate Unlearning lectures - ●​ Exact Unlearning - Unlearned model & retrained model to be distributionally identical. ●​ Unlearning via Differential Privacy - Unlearned model & retrained model to be distributionally close. ●​ Example Unlearning - Train, retain, and forget sets are often clearly defined. ●​ Concept Unlearning - Train, retain, or forget sets are poorly specified or just not ●​ specified at all.','Review Exact vs Approximate Unlearning.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q2',3,'Machine Unlearning','assignment','medium','single','What is the primary goal of “Machine Unlearning”?','["To increase the training speed of a model.", "To add more data to an existing model without retraining.", "To remove the influence of specific training data from a trained model.", "To improve the accuracy of a model on new, unseen data."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Unlearning [8:41-9:36] - Machine Unlearning can be broadly described as removing the influences of training data from a trained model.','Review Machine Unlearning.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q3',3,'GDPR Article 17','assignment','medium','single','What is GDPR’s Article 17 about in the context of Machine Learning?','["Right to be remembered", "Right to be forgotten", "Right to be modified", "Right to be distributed"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Unlearning [11:35-15:50] - GDPR’s Article 17 is the right to erasure or right to be forgotten.','Review GDPR Article 17.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q4',3,'SISA','assignment','medium','single','In the SISA framework, what is the benefit of using “shards” and “slices”?','["It increases the overall accuracy of the model.", "It ensures that unlearned data never contributes to other components.", "It allows the model to learn from toxic data safely.", "It eliminates the need for any retraining."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Unlearning [29:44-30:02] - Algorithm is the proof: SISA by design unlearned data never contributed to other components (split).','Review SISA.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q5',3,'Membership Inference','assignment','medium','single','What is “Membership Inference Attack”?','["To distinguish whether specific training data was used to train a model.", "To add new members to a training dataset.", "To speed up the unlearning process.", "To verify the architecture of the model."]'::jsonb,'[0]'::jsonb,NULL,0.0,'Approximate Unlearning [11:55-13:48] - Membership inference attacks aim to distinguish training data from unseen data.','Review Membership Inference.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q6',3,'Gradient Ascent','assignment','medium','single','Which unlearning method involves increasing the training loss on the forget set?','["KL Divergence", "Direct Preference Optimization", "Gradient Ascent", "Gradient Difference"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Evaluation of Unlearning and Graph Unlearning Part 1 [17:20-19:08] - Gradient Ascent: Mess up predictions on the forget set by increasing the usual training loss on the forget set.','Review Gradient Ascent.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q7',3,'Representation Engineering','assignment','medium','single','According to the lecture, what is “Representation Engineering”?','["A bottom-up approach focusing on individual neurons.", "Modifying representation vectors to control model traits.", "A method for increasing the parameter count of a model.", "Re-labeling all data points in a dataset to fix biases."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Evaluation of Unlearning and Graph Unlearning Part 1 [30:35-33:10] - Modify the representation vectors to modify the model outputs.','Review Representation Engineering.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q8',3,'SISA Retraining','assignment','medium','single','In the context of the SISA framework, how does the system minimize the cost of retraining when a data point must be unlearned?','["By using gradient ascent on only the affected data points.", "By applying a differential privacy constraint to the aggregation layer.", "By flipping the labels of the forget set and performing few-shot.", "By retraining only the constituent model whose shards contain the point to be unlearned."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Unlearning [25:00-29:43] - SISA training: data is divided in shards, which are themselves divided into slices. One constituent model is trained on each shard by presenting it with incrementally many slices and saving its parameters before the training set is augmented with a new slice. When data needs to be unlearned, only one of the constituent models whose shards contain the point to be unlearned needs to be retrained — retraining can start from the last parameter values saved before including the slice containing the data point to be unlearned.','Review SISA Retraining.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q9',3,'Fundamental Knowledge','assignment','medium','single','According to the lecture, why is unlearning fundamental facts like “the sun rises every day” considered more difficult than unlearning infrequent textual occurrences, such as car accidents?','["Fundamental knowledge is deeply embedded in the model’s implicit knowledge graph.", "Fundamental facts are typically protected by guardrails.", "Models are primarily trained on Wikipedia, which contains these facts.", "Differential privacy guarantees fall off more quickly for fundamental facts."]'::jsonb,'[0]'::jsonb,NULL,0.0,'Evaluation of Unlearning and Graph Unlearning Part 1 [25:25-27:16] - A piece of knowledge can be so embedded in the model’s implicit knowledge graph that it cannot be unlearned without introducing contradictions and harming the model’s utility.','Review Fundamental Knowledge.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q10',3,'Model Utility','assignment','medium','single','Which unlearning evaluation metric focuses on whether the unlearning process negatively affects the model’s performance on the “retrain data” or unrelated tasks?','["Efficiency", "Forgetting Quality", "Model Utility", "Membership Inference"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Approximate Unlearning [25:55-27:35] - Model utility: Do we harm performance on the retain data or orthogonal tasks?','Review Model Utility.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q11',3,'WMDP','assignment','medium','multi','The WMDP benchmark measures hazardous knowledge in which specific areas? (Select all that apply.)','["Biosecurity/Bioweapons", "Cybersecurity", "Chemical security", "Financial market manipulation"]'::jsonb,'[0, 1, 2]'::jsonb,NULL,0.0,'Evaluation of Unlearning and Graph Unlearning Part 1 [19:45-21:40] - Unlearning dangerous knowledge, specifically on biosecurity, cybersecurity, and chemical security.','Review WMDP.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w3_q12',3,'Graph Unlearning','assignment','medium','multi','Which methods are used for Edge Unlearning? (Select all that apply.)','["GraphEraser", "GUIDE", "Projector", "GraphdEditor", "GNNDelete", "MEGU"]'::jsonb,'[0, 3, 4, 5]'::jsonb,NULL,0.0,'Evaluation of Unlearning and Graph Unlearning Part 2 [13:14-16:53] - The chart has checkmarks showing the methods used for each type of unlearning.','Review Graph Unlearning.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q1',4,'Statistical vs ML Bias','assignment','medium','single','How does the definition of “bias” in CS/ML differ from Statistics?','["Statistics focuses on societal values, while CS/ML focuses on mathematical deviations.", "Statistics defines it as a systematic error in data collection/interpretation, while CS/ML defines it as a systematic favoritism towards certain groups/outcomes.", "CS/ML focuses on rationality in judgment, while Statistics focuses on algorithmic performance.", "There is no difference; both define bias as a systematic deviation from rationality."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Bias - I [18:48-19:41] - ●​ Statistics: Systematic error in the collection, analysis, or interpretation of data ●​ CS/ML: Systematic favoritism or discrimination towards certain groups/outcomes','Review Statistical vs ML Bias.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q2',4,'Bias Impact','assignment','medium','single','According to the slides, when does bias become a problem?','["Bias is a problem at all times because humans are not perfect.", "It is only a problem when it occurs in the data collection phase.", "It is only a problem when it can have a negative impact.", "It is only a problem when the model is not 100% accurate."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Bias - I [21:50-23:09] - Bias is always there – humans are not perfect. It is only a problem when it can have a negative impact.','Review Bias Impact.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q3',4,'InSaAF','assignment','medium','single','Which metric is proposed in the InSaAF study to encapsulate both fairness and accuracy in the Indian legal landscape?','["Demographic Parity Score", "Perspective API Score", "Legal Grounding Score", "β-weighted Legal Safety Score"]'::jsonb,'[3]'::jsonb,NULL,0.0,'Bias - II [14:01-14:15] - β-weighted Legal Safety Score (LSSβ), which encapsulates both the fairness and accuracy aspects of the LLM.','Review InSaAF.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q4',4,'Microsoft Tay','assignment','medium','single','What was the primary issue with Microsoft’s chatbot “Tay”?','["It was unable to process text correctly.", "It posted unintended offensive tweets due to malicious user intent.", "It could only generate content related to the United States.", "It was too slow to respond to users."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Bias - II [17:46-19:30] - Refer to the article given in the lecture (https://www.theverge.com/2016/3/24/11297050/tay-microsoft-chatbot-racist)','Review Microsoft Tay.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q5',4,'Midjourney Bias','assignment','medium','single','Analysis of AI-generated images from Midjourney showed which of the following biases regarding specialized roles?','["Only younger women were shown in specialized roles.", "Only older men were shown in specialized roles.", "Older women were frequently depicted as news analysts.", "Specialized roles always featured diverse racial representation."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Bias - II [21:35-23:40] - For non-specialised job titles, Midjourney returned images of only younger men and women. For specialised roles, both younger and older people were shown – but the older people were always men.','Review Midjourney Bias.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q6',4,'Bias Pipeline','assignment','medium','multi','According to “The Source of Bias” ML pipeline, at which stage can bias be introduced? (Select all that apply.)','["Collecting and labelling data", "Training using chosen metrics and objectives", "Models deployed in production", "Users see an effect"]'::jsonb,'[0, 1, 2, 3]'::jsonb,NULL,0.0,'Source of Bias [0:15-2:28] - Each stage of the pipeline leaves an opening for bias to be introduced.','Review Bias Pipeline.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q7',4,'CrowS-Pairs','assignment','medium','single','What does each pair in the CrowS-Pairs dataset consist of?','["One stereotype sentence and one neutral sentence", "One biased sentence and one unbiased sentence", "One stereotype sentence and one opposite stereotype sentence", "One stereotype sentence and one less stereotype sentence"]'::jsonb,'[3]'::jsonb,NULL,0.0,'Bias - I [25:14-28:50] - In this dataset, for each example, the two sentences are minimally distant.','Review CrowS-Pairs.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q8',4,'Latent Design Choice','assignment','medium','single','Which of the following is a "latent" design choice that can lead to bias in a dataset?','["Choosing to use only English-language phrases.", "Using systematic favoritism towards a specific outcome.", "Manually editing every data point to be offensive.", "Refusing to use any AI models in production."]'::jsonb,'[0]'::jsonb,NULL,0.0,'A latent design choice is an unstated decision that implicitly introduces bias. Choosing only English-language data is a latent choice because it implicitly excludes non-Western data, leading to a skewed, Western-aligned dataset.','Review Latent Design Choice.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q9',4,'Contrastive Learning','assignment','medium','multi','Which of the following is the correct setting for contrastive learning? (Select all that apply.)','["Irrespective of the sentences, minimise the distance between their embeddings.", "Irrespective of the sentences, maximise the distance between their embeddings.", "If sentences are similar, minimise the distance between their embeddings.", "If sentences are different, minimise the distance between their embeddings.", "If sentences are different, maximise the distance between their embeddings.", "If sentences are different, minimise the distance between their embeddings"]'::jsonb,'[2, 4]'::jsonb,NULL,0.0,'Contrastive learning trains models by pulling similar items together and pushing dissimilar items apart. It achieves this by minimizing the embedding distance for similar sentences and maximizing the distance for different ones.','Review Contrastive Learning.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q10',4,'Stereotype','assignment','medium','single','What is a “stereotype”?','["A factual statement that applies to all humans.", "A scientifically proven characteristic.", "A legal rule used to govern a society.", "A widely held belief about some group."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Bias - I [19:47-21:48] - Stereotypes: A widely held belief about some group/entity.','Review Stereotype.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q11',4,'Reporting Bias','assignment','medium','single','A sentiment-analysis model is trained to predict whether book reviews are positive or negative based on a corpus of user submissions to a popular website. The majority of reviews in the training dataset reflect extreme opinions (reviewers who either loved or hated a book), because people were less likely to submit a review of a book if they did not respond to it strongly. As a result, the model is less able to correctly predict the sentiment of reviews that use more subtle language to describe a book. Which type of bias is this?','["Reporting bias", "Historical bias", "Automation bias", "In-group bias"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Please refer to the link for an explanation: https://developers.google.com/machine-learning/crash-course/fairness/types-of-bias','Review Reporting Bias.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w4_q12',4,'Bias Categories','assignment','medium','multi','As per the lecture, which of the following is a/are a category of bias? (Select all that apply.)','["Gender", "Race", "Scientific Facts", "Profession", "Currency exchange rates"]'::jsonb,'[0, 1, 3]'::jsonb,NULL,0.0,'Bias - I [23:10-25:13] -Among the options, gender, race, and profession are considered categories of bias.','Review Bias Categories.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q1',5,'StereoSet','assignment','medium','single','What should be the language modelling (lms) for an ideal model in the StereoSet benchmark?','["25", "50", "75", "100"]'::jsonb,'[3]'::jsonb,NULL,0.0,'Bias - III [7:24-11:17] - The lms of an ideal language model will be 100.','Review StereoSet.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q2',5,'CrowS-Pairs Score','assignment','medium','single','In the CrowS-Pairs benchmark, what does a score of 100% indicate?','["The model has no social bias.", "The model always prefers anti-stereotypical sentences.", "The model always prefers stereotypical sentences.", "The model is an ideal language model."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Bias - III [7:24-11:17] - Stereotype score (ss) is the percentage of examples where the model prefers stereotypical associations over anti-stereotypical ones.','Review CrowS-Pairs Score.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q3',5,'Catastrophic Forgetting','assignment','medium','single','What phenomenon occurs when fine-tuning all parameters of a large language model (LLM) to remove bias, leading to a drop in general performance?','["Model Drifting", "Catastrophic Forgetting", "Overfitting", "Gradient Explosion"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Catastrophic forgetting occurs when fine-tuning an LLM on a specific task, such as bias removal, causes it to lose previously learned knowledge and general capabilities.','Review Catastrophic Forgetting.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q4',5,'CDA','assignment','medium','single','What is Counterfactual Data Augmentation (CDA)?','["Re-balancing a corpus by swapping bias attribute words in a dataset.", "Adding more stereotypical sentences to a dataset to make it more biased.", "Removing all bias-attributed words in a dataset.", "Ensuring the dataset has an equal number of biased and unbiased samples."]'::jsonb,'[0]'::jsonb,NULL,0.0,'Bias - IV [35:49-37:57] - CDA involves re-balancing a corpus by swapping bias attribute words (e.g., he/she) in a dataset.','Review CDA.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q5',5,'NeMo Guardrails','assignment','medium','single','Which toolkit is used to add programmable guardrails to LLM-based conversational applications to control outputs?','["GPT-4", "NVIDIA NeMo", "CoDi", "MAFIA"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Bias - IV [13:16-15:50] - NVIDIA NeMo is an open-source toolkit for easily adding programmable guardrails to LLM-based conversational applications.','Review NeMo Guardrails.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q6',5,'Prompt Variations','assignment','medium','single','Match the following example to the correct prompt variation. i. The image shows a subject with the occupation ''Chief Executive Officer''. Based on the image and this information, what is the gender of the person? (a) male (b) female (c) no preference ii. Looking at this image alone, who would you hire to be the CEO of a Fortune 500 company? (a) person in the image (b) someone else (c) no preference','["i -> Informed, ii -> Informed", "i -> Informed, ii -> Blind", "i -> Blind, ii ->Informed", "i -> Blind, ii -> Blind"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Bias in VLM''s [15:05-19:02] - (i) contains the details about the image and explicitly asks the gender, while (ii) gives no extra information about the image.','Review Prompt Variations.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q7',5,'CrowS-Pairs Bias Types','assignment','medium','multi','The CrowS-Pairs benchmark includes which of the following types of social bias? (Select all that apply.)','["Sexual orientation", "Socioeconomic status", "Political ideology", "Physical appearance"]'::jsonb,'[0, 1, 3]'::jsonb,NULL,0.0,'Bias III [14:50-15:40] - Sexual orientation, socioeconomic status, and physical appearance are all part of social bias in the CrowS-Pairs benchmark.','Review CrowS-Pairs Bias Types.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q8',5,'Gender Bias Datasets','assignment','medium','multi','Which of the following datasets are specifically designed for measuring gender-related biases? (Select all that apply.)','["BOLD", "RedditBias", "WinoBias", "Winogender"]'::jsonb,'[2, 3]'::jsonb,NULL,0.0,'Bias - III [33:14-36:50] and Bias - IV [0:00-4:24] - Winogender and WinoBias both measure gender-related bias.','Review Gender Bias Datasets.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q9',5,'PMI','assignment','medium','numeric','You are performing a bias audit on a corpus with 𝑁 = 1000 total documents. Calculate the PMI between an identity label 𝑤𝑖 and a specific descriptive word 𝑤𝑗. ● The identity label appears in 100 documents. ● The descriptive word appears in 50 documents. ● Both words co-occur in the same document 20 times.','[]'::jsonb,'[]'::jsonb,2.0,0.0,'Original numerical assignment question. The accepted answer follows the supplied solution sheet.','Review PMI.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q10',5,'Word Frequency Threshold','assignment','medium','single','What is the minimum threshold a word has to appear in the corpus for it to be considered when performing word association analysis?','["2 times", "5 times", "10 times", "20 times"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Bias Handon Part 1 [5:44-7:08] - Terms that occur less than 10 times in the corpus should not be considered.','Review Word Frequency Threshold.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q11',5,'Gender-bleached Input','assignment','medium','single','What is the "Gender-bleached" input method used for?','["To remove all images containing humans from the training set.", "To study societal bias in generated output by providing input that blurs gender.", "To increase the \"Neutral\" accuracy above the random baseline.", "To ensure the model can only identify objects rather than social attributes."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Bias in VLM’s [8:41-9:08] - Gender-bleached input to study gender bias in generated output.','Review Gender-bleached Input.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w5_q12',5,'COBIAS','assignment','medium','single','What is the main goal of the COBIAS framework when assessing bias?','["To automatically remove all stereotypical words from a model''s training data.", "To increase the speed at which a model generates text by reducing the number of words used.", "To ensure that models only use gender-neutral pronouns like \"they\" in every conversation.", "To evaluate how much a model relies on specific contexts before deciding if a statement is truly biased."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Bias - IV [17:39-18:46] - COBIAS is designed to understand the concept of inputs by considering the diverse situations in which they may arise.','Review COBIAS.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q1',6,'Cryptography Limitations','assignment','medium','multi','According to the lecture, why would standard cryptographic solutions be unsuitable for AI model privacy? (Select all that apply.)','["It is unclear whether all complex functions can be effectively evaluated from in the encryption space.", "Evaluation in encrypted space is computationally expensive.", "As the model scales, cryptographic keys become impossible to manage.", "Encryption models cannot be used for binary classification tasks."]'::jsonb,'[0, 1]'::jsonb,NULL,0.0,'Data Privacy [4:06-6:22] - There are two reasons why cryptographic solutions are not suitable. First, it is unclear whether you can do inference in an encrypted space. Second, encryption is an expensive solution.','Review Cryptography Limitations.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q2',6,'Model Privacy Risk','assignment','medium','single','In the context of healthcare data, why might a trained binary classification model still pose a privacy risk even if the raw data is not directly released?','["The model weights occupy too much storage space.", "Binary classifiers are inherently less secure than multi-class ones.", "An adversary can reverse-engineer sensitive training data.", "The labels used for training are usually public knowledge."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Data Privacy [1:45-4:06] - An adversary can reverse-engineer sensitive personal information such as healthcare or financial data given a simple binary classification model.','Review Model Privacy Risk.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q3',6,'Netflix De-anonymization','assignment','medium','single','How were users able to deanonymize the “anonymized” Netflix dataset?','["By obtaining the meta-data of the dataset.", "By brute-forcing the sparse matrix to reveal the missing entries.", "By using cryptanalytic attacks to decode user information.", "By using an auxiliary public database, such as IMDb, to correlate ratings."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Data Privacy [8:55-12:46] - They were able to deanonymize the Netflix dataset by using an auxiliary database (IMDb) and correlating the two.','Review Netflix De-anonymization.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q4',6,'Randomized Response','assignment','medium','single','In the randomized response algorithm presented in the lecture, what is the minimum probability that the truthful answer is revealed?','["10%", "25%", "50%", "75%"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Data Privacy [21:25-24:12] - ε > 0 means that the truth will be revealed ε 𝑒 with a probability of ε > 50%. 1+ 𝑒','Review Randomized Response.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q5',6,'Privacy-Utility Tradeoff','assignment','medium','single','To maximize utility, how should the privacy parameter ε be adjusted?','["ε should be maximum for privacy, ε should be minimum for utility", "ε should be minimum for privacy, ε should be minimum for utility", "ε should be maximum for privacy, ε should be maximum for utility", "ε should be minimum for privacy, ε should be maximum for utility", "ε is unrelated"]'::jsonb,'[3]'::jsonb,NULL,0.0,'Data Privacy [1:00:00 - 1:01:20] - If ε is large, 𝑥𝑖 and 𝑧𝑖 are easier to distinguish, which increases utility, and vice versa. ε controls the privacy-utility tradeoff.','Review Privacy-Utility Tradeoff.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q6',6,'Randomized Response Calculation','assignment','medium','numeric','An organization surveys 100 people and asks whether they voted for a certain party. To protect respondents'' privacy, the organization uses the randomized response technique with ε = 0. 5. Out of 100 respondents, 60 reported “Yes” and 40 reported “No.” Estimate the true number of people whose actual answer was “Yes”. Round to the nearest whole number.','[]'::jsonb,'[]'::jsonb,91.0,0.0,'Original numerical assignment question. The accepted answer follows the supplied solution sheet.','Review Randomized Response Calculation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q7',6,'Trusted Curator','assignment','medium','single','Which trust scenario correctly describes the differential privacy model?','["Trust the curator; Trust the world", "Do not trust the curator; Trust the world", "Trust the curator; Do not trust the world", "Do not trust the curator; Do not trust the world"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Data Privacy [1:06:06-1:11:00] - In differential privacy, surveyors trust the curator to give their information to them but want their information to be privatized when the computed function is released to the world.','Review Trusted Curator.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q8',6,'Sensitivity','assignment','medium','single','In the Laplace Mechanism, how is the sensitivity (∆) defined for a function 𝑓?','["The average difference between 𝑓(𝑋) and 𝑓(𝑋'') for all neighbouring 𝑋 and 𝑋''.", "The maximum absolute difference between 𝑓(𝑋) and 𝑓(𝑋'') for any two neighboring 𝑋 and 𝑋''.", "The standard deviation of the function 𝑓.", "The minimum difference between 𝑓(𝑋) and 𝑓(𝑋'') for any two neighboring 𝑋 and 𝑋''."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Differential Privacy [21:30-22:34] - Sensitivity (∆) in the Laplace mechanism measures how sensitive a function 𝑓 is to a single input change. It is the maximum absolute difference |𝑓(𝑋) − 𝑓(𝑋'')| over all neighboring datasets 𝑋 and 𝑋'' that differ by one element.','Review Sensitivity.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q9',6,'DP Guarantee','assignment','medium','single','According to Cynthia Dwork''s definition of ε-differential privacy, for all neighbouring datasets 𝑋 and 𝑋'', the probability that a mechanism 𝑀 on 𝑋 generates an output in subset 𝑆 divided by the probability that a mechanism 𝑀 on 𝑋'' generates an output in subset 𝑆 is at most: ε','["𝑒", "ε", "1/ε 𝑒", "ε"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Differential Privacy [9:57-15:02] - A mechanism 𝑀 is said to be ε 𝑃𝑟(𝑀(𝑋) ϵ 𝑆) ε -differential private if 𝑃𝑟(𝑀(𝑋'') ϵ 𝑆) ≤ 𝑒 .','Review DP Guarantee.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q10',6,'Neighboring Datasets','assignment','medium','single','What property of neighboring data sets 𝑋 and 𝑋'' is used to prove the privacy guarantee of Randomized Response?','["They have zero correlation.", "They differ by 99% of the elements in the set.", "They are disjoint sets.", "They differ by only one element."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Data Privacy [24:29-25:58] - 𝑋 and 𝑋'' are two datasets where 𝑋 = 𝑋'' ∀ 𝑖 ϵ {1 ... ( 𝑛 − 1)}, meaning they differ by only one element of index 𝑖 = 𝑛.','Review Neighboring Datasets.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q11',6,'Laplace Noise','assignment','medium','single','For a fixed ε, if a function being computed is highly sensitive (large ∆), how does it affect the noise added to the Laplace mechanism?','["Less noise is added.", "More noise is added.", "The noise remains unchanged.", "Noise is irrelevant."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Differential Privacy [27:14-31:00] - The more sensitive the function, the more noise should be added.','Review Laplace Noise.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w6_q12',6,'Laplace vs Randomized Response','assignment','medium','single','Comparing the Laplace mechanism and randomized response, how does the required number of respondents 𝑛 differ to achieve the same privacy–utility trade-off?','["The Laplace mechanism requires quadratically more people.", "The Laplace mechanism requires quadratically fewer people.", "Both require the same number of people.", "The number of people to survey does not matter."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Differential Privacy [50:18-53:02] - If you trust the curator, then you would have to survey a quadratically lesser number of people to achieve the same privacy-utility tradeoff using the Laplace mechanism than not trusting the curator.','Review Laplace vs Randomized Response.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q1',7,'Approximate DP','assignment','medium','single','In Approximate Differential Privacy, what does δ represent?','["The strict upper bound of the probability of the mechanism 𝑀.", "The estimated noise added to the Laplace Mechanism.", "The average difference between all the data points in the datasets 𝑋 and 𝑋''.", "A leeway for small-probability events where ε-differential privacy may fail."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Approximate Differential Privacy [6:50-9:26] - δ is a small leeway for low probability events where ε-differential privacy property may not hold true.','Review Approximate DP.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q2',7,'Gaussian Mechanism','assignment','medium','single','Compared to the Laplacian mechanism, how does the Gaussian mechanism scale the amount of noise added when releasing D different outputs?','["It adds noise linearly proportional to D.", "It adds noise proportional to the square root of D.", "It adds noise exponentially proportional to D.", "It adds the same amount of noise."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Approximate Differential Privacy [18:00-20:58] - The Guassian Mechanism requires quadratically less amount of noise to become in terms of number of output that you''re releasing.','Review Gaussian Mechanism.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q3',7,'DP Composition','assignment','medium','multi','Which of the following are properties of Approximate Differential Privacy? (Select all that apply.)','["It satisfies the property of post-processing, meaning any data-independent computation applied to the output will not make it less (ε, δ)-differentially private.", "It guarantees privacy even when δ is significantly larger than 1/𝑛 (where 𝑛 is the number of individuals in a dataset).", "It satisfies composition, meaning if you have 𝑘 mechanisms that are all (ε, δ) -differentially private, then the combined mechanism is (𝑘ε, 𝑘δ)-differentially private.", "It guarantees that the output distributions of the algorithm are completely identical for any two neighboring datasets."]'::jsonb,'[0, 2]'::jsonb,NULL,0.0,'Approximate Differential Privacy [23:40-34:53] - Approximate differential privacy has two properties: post-processing and composition.','Review DP Composition.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q4',7,'Gaussian Utility','assignment','medium','single','According to the lecture, what is the primary advantage of using the Gaussian Mechanism?','["Zero chance of privacy leakage.", "Faster computational time for calculating probabilities.", "Better utility due to adding quadratically less noise.", "Eliminates the need for a trusted curator."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Approximate Differential Privacy [14:45-22:55] - Gaussian mechanism gains better utility with quadratically less amount of noise.','Review Gaussian Utility.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q5',7,'Revenue Calculation','assignment','medium','numeric','There are three buyers whose valuations are 15, 20, and 135, respectively. What is the absolute difference in revenue when the price of a digital good changes from 14 to 18? (Round your answer to the nearest whole number.)','[]'::jsonb,'[]'::jsonb,6.0,0.0,'Original numerical assignment question. The accepted answer follows the supplied solution sheet.','Review Revenue Calculation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q6',7,'Exponential Mechanism','assignment','medium','single','How does the Exponential Mechanism select a price ℎ ϵ 𝐻?','["With probability proportional to the inverse of the price. ε 2δ 𝑆(𝑥, ℎ)", "With probability proportional to 𝑒 . δ 2ε 𝑆(𝑥, ℎ)", "With probability proportional to 𝑒 .", "Uniformly at random from all prices below the maximum valuation."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Exponential Mechanism [14:11-15:00] - Select ℎ ϵ 𝐻 with probability ε 2δ 𝑆(𝑥, ℎ) proportional to 𝑒 .','Review Exponential Mechanism.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q7',7,'Exponential Mechanism Privacy','assignment','medium','single','What privacy guarantee does the Exponential Mechanism provide for buyers'' valuations?','["(ε, δ)-Differential Privacy", "ε-Differential Privacy", "K-Anonymity", "Concentrated Differential Privacy"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Exponential Mechanism [15:53-18:15] - Exponential mechanism is Epsilon differentially private for the given valuations.','Review Exponential Mechanism Privacy.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q8',7,'Exponential Mechanism Utility','assignment','medium','single','What is the utility guarantee provided by the Exponential Mechanism?','["It guarantees the absolute highest possible revenue every time.", "It does not guarantee positive revenue every time.", "It guarantees that the revenue will not be significantly lower than the optimal revenue.", "The guarantee will exactly match the median valuation."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Exponential Mechanism [18:15-22:35] - It guarantees that the revenue will not be significantly lower than the optimal revenue.','Review Exponential Mechanism Utility.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q9',7,'Statistical Parity','assignment','medium','single','In Statistical Parity, for a protected group 𝐶 and a classifier 𝑀, what is the parity value for an ideal classifier?','["-1", "0", "0.5", "1"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Fairness in Machine Learning [47:03-50:41] - An ideal classifier has a parity equal to 0.','Review Statistical Parity.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q10',7,'COMPAS','assignment','medium','multi','According to the data comparing White and African American defendants in risk assessments, which of the following statements are true? (Select all that apply.)','["White defendants were labeled lower risk yet did re-offend at a higher rate than African American defendants.", "African American defendants were labeled higher risk but didn''t re-offend at a higher rate than White defendants.", "White defendants had a higher rate of being labeled higher risk without re-offending than African American defendants.", "African American defendants had a lower rate of being labeled lower risk yet re-offending compared to White defendants. Explanation: Fairness in Machine Learning [19:42-21:38] - According to the table: ● A higher percentage of African Americans were labelled as higher risk but didn’t re-offend ● A higher percentage of White people were labelled as low risk but did re-offend. ● A lower percentage of African Americans were labelled as lower risk yet re-offended compared to White people."]'::jsonb,'[0, 1, 3]'::jsonb,NULL,0.0,'Fairness in Machine Learning [19:42-21:38] - According to the table: ●​ A higher percentage of African Americans were labelled as higher risk but didn’t re-offend ●​ A higher percentage of White people were labelled as low risk but did re-offend. ●​ A lower percentage of African Americans were labelled as lower risk yet re-offended compared to White people.','Review COMPAS.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q11',7,'Embedding Bias','assignment','medium','single','Based on the analysis of biases in word embeddings from Wikipedia and Social Media, which of the following professions was associated with sexist prejudice towards men?','["Nurse", "Teacher", "Pharmacist", "Cameraman"]'::jsonb,'[3]'::jsonb,NULL,0.0,'Fairness in Machine Learning [24:44-28:10] - According to the lecture, “Cameraman” is a profession that is associated with sexist prejudice towards men.','Review Embedding Bias.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w7_q12',7,'Fair PCA','assignment','medium','single','The goal of Fair PCA is to find a PCA solution 𝑈 = [𝑈𝐴, 𝑈𝐵] such that the reconstruction losses of groups A and B (where A is the protected group) are:','["Equal", "Unequal", "The protected group has a lower reconstruction loss", "The protected group has a higher reconstruction loss"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Fairness in Machine Learning [40:05-44:56] - At optimality, Fair PCA minimizes the maximum loss between the groups, which mathematically forces their average reconstruction errors to be equal.','Review Fair PCA.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q1',8,'Pixel Attribution','assignment','medium','single','Which of the following best describes Pixel Attribution Methods?','["They compress neural network layers to reduce model size.", "They automatically remove backdoor triggers from poisoned datasets.", "They convert text datasets directly into image representations.", "They highlight pixels that were relevant for a certain image classification."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Interpretability - I [3:40-4:55] - Pixel Attribution Methods highlight the pixels that were relevant for a certain image classification by a neural network','Review Pixel Attribution.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q2',8,'Occlusion','assignment','medium','single','Which of the following pixel attribution methods involve manipulating parts of an image to generate explanations?','["Gradient-based methods", "Occlusion-based methods", "Mechanical methods", "Top-down methods"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Interpretability - I [6:33-7:25] - Occlusion- or perturbation-based: Methods like SHAP and LIME manipulate parts of the image to generate explanations (model-agnostic).','Review Occlusion.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q3',8,'Saliency Sanity Check','assignment','medium','single','What should happen to a saliency map if a model that genuinely captures higher-level class concepts has its layers randomized?','["The map should invert its colors.", "The map should remain identical.", "The map should change significantly.", "The map should become a blank image."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Interpretability - I [20:11-22:28] - If a model captures higher-level class concepts, then saliency maps should change as the model is being randomized.','Review Saliency Sanity Check.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q4',8,'LIME Validation','assignment','medium','multi','How can we validate the explanations given by LIME? (Select all that apply.)','["By using prior knowledge.", "By randomizing the model’s layers.", "By using human annotators.", "By applying adversarial perturbations."]'::jsonb,'[0, 2]'::jsonb,NULL,0.0,'Interpretability - I [25:10-27:03] - Using prior knowledge, we can validate the explanations. Human annotation can be used to decide whether the model''s explanations are correct.','Review LIME Validation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q5',8,'Top-down Interpretability','assignment','medium','single','Which of the following interpretability approaches involves locating information in a model without fully understanding how it is processed?','["Mechanistic interpretability", "Top-down interpretability", "Feature-based visualization", "Game-theoretic approach"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Interpretability - II [9:57-11:58] - Top-down locates information in a model without full understanding of how it is processed','Review Top-down Interpretability.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q6',8,'Probing','assignment','medium','single','What is the primary function of probing in interpretability?','["To inject hidden trojans into public datasets during training.", "To check whether representations encode information reliably", "To optimize latent space interpolation for image generation", "To completely reverse-engineer all node-to-node algorithmic connections in large language models."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Interpretability - II [13:57-16:33] - Probing loosely refers to a class of methodologies in interpretability to check whether representations encode information reliably for some specific task.','Review Probing.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q7',8,'Attack Vectors','assignment','medium','multi','According to the lecture, which of the following are Attack Vectors? (Select all that apply.)','["API keys", "Public Datasets", "HuggingFace models", "A downloadable execution file"]'::jsonb,'[1, 2]'::jsonb,NULL,0.0,'Interpretability - II [20:32-21:23] - Public datasets and model sharing libraries are some examples of attack vectors.','Review Attack Vectors.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q8',8,'LIME Objective','assignment','medium','single','Consider the following equation for LIME: What do the components 𝐿 and Ω(𝑔) represent?','["𝐿 measures how unfaithful the explanation model 𝑔 is in approximating 𝑓 locally (weighted by π𝑥, while Ω(𝑔) measures the complexity/interpretability penalty of the explanation model.", "𝐿 represents the global accuracy of the black-box model 𝑓, and Ω(𝑔) represents the total number of convolutional layers.", "𝐿 is the adversarial perturbation budget, and Ω(𝑔) is the learning rate of the surrogate model.", "𝐿 calculates the exact Shapley values, and Ω(𝑔) computes the gradient with respect to input pixels."]'::jsonb,'[0]'::jsonb,NULL,0.0,'Interpretability - I [32:03-34:57] - In LIME''s objective function, 𝐿 quantifies how poorly the simple explanation model 𝑔 approximates the complex black-box model 𝑓 within the local neighborhood defined by π𝑥, while Ω(𝑔) penalizes model complexity to ensure the resulting explanation remains simple and interpretable for humans.','Review LIME Objective.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q9',8,'Neural Cleanse','assignment','medium','single','What is the primary goal of Neural Cleanse when detecting Trojans in neural networks?','["To fine-tune the model using a 0.05% poisoned dataset", "To reverse-engineer potential triggers", "To prune the entire first-layer weights of a classifier", "To train a neural network using high-dimensional pooling layers"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Interpretability - II [26:57-31:36] - If we know the general form of the attack, we can reverse-engineer the Trojan by searching for a trigger and target label.','Review Neural Cleanse.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q10',8,'Top-down vs Mechanistic','assignment','medium','single','How does top-down interpretability differ from mechanistic interpretability?','["Top-down focuses on algorithmic node-to-node connections, whereas mechanistic looks at global activity of populations of neurons.", "Top-down localizes information in a model and looks at representational spaces, while mechanistic attempts to reverse-engineer neural networks at the neuron level.", "Top-down requires full mathematical proof of model weights, whereas mechanistic is entirely model-agnostic.", "Top-down can only be applied to text-based saliency maps, whereas mechanistic only applies to GANs. Explanation: Interpretability - II [6:27-11:58] - Mechanistic: Reverse-engineer neural Networks; Top-Down: Locate information in a model without full understanding of how it is processed."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Interpretability - II [6:27-11:58] - Mechanistic: Reverse-engineer neural Networks; Top-Down: Locate information in a model without full understanding of how it is processed.','Review Top-down vs Mechanistic.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q11',8,'SHAP','assignment','medium','single','What game-theoretic concept does SHAP (Shapley Additive exPlanations) explain about the output of any machine learning model?','["Nash Equilibrium", "Pareto Optimality", "Shapley Values", "Minimax Theorem Explanation: Interpretability - I [35:20-39:39] - Connects optimal credit allocation with local explanations using the classic Shapley values from game theory and their related extensions."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Interpretability - I [35:20-39:39] - Connects optimal credit allocation with local explanations using the classic Shapley values from game theory and their related extensions.','Review SHAP.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w8_q12',8,'LIME and SHAP','assignment','medium','multi','Regarding LIME and SHAP, which of the following statements are true? (Select all that apply.)','["They generate global explanations that apply uniformly across the entire dataset.", "They are model-agnostic methods that can work on any black-box model.", "They are restricted solely to image datasets and cannot handle natural language data.", "They can be computationally expensive to compute compared to direct gradient-based visualizations."]'::jsonb,'[1, 3]'::jsonb,NULL,0.0,'Interpretability - I [25:09-39:39] - Works on any black-box model with many data types.','Review LIME and SHAP.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q1',9,'Vertical vs Horizontal Regulation','assignment','medium','single','What is the difference between "vertical" and "horizontal" AI regulation?','["Vertical regulates the hardware, while horizontal regulates the software.", "Vertical regulation is completely market-based, while horizontal is purely state-controlled.", "Vertical regulation applies existing sector-specific laws to AI, while horizontal regulation creates broad, new risk-based laws across all sectors.", "Vertical regulation only applies to the industry, while horizontal applies to the industry and its customers."]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 1 [40:25-43:12] - Vertical regulation tweaks existing laws for specific industries, whereas horizontal regulation attempts to classify and govern the technology itself across all sectors.','Review Vertical vs Horizontal Regulation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q2',9,'Privacy Guardrails','assignment','medium','single','Why is data privacy considered a relatively better-understood guardrail compared to model explainability?','["Explainability has exact mathematical bounds, whereas privacy cannot be measured mathematically.", "Privacy can be controlled by improving the model’s accuracy, while explainability depends mainly on the size of the training dataset.", "Privacy can be formally bounded and guaranteed with mathematical frameworks.", "There are far less constraints in ensuring data privacy than explainability."]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 2 [14:20-14:50] - Mathematical frameworks like differential privacy or cryptography provide proven security guarantees, explainability is black-box and remains harder to formally bound.','Review Privacy Guardrails.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q3',9,'Human Agency','assignment','medium','single','According to the lecture, as AI systems become autonomous agents capable of performing complex tasks independently, what is the main trade-off that occurs regarding human decision-making.','["Individual human agency decreases as decision-making is delegated to autonomous AI systems.", "Human decision-making increases because autonomous AI agents provide more information and recommendations to users.", "Human agency remains unchanged because autonomous AI systems only perform tasks without affecting human decisions.", "Human decision-making becomes more reliable because AI agents completely eliminate uncertainty and errors from the decision-making process."]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 2 [33:10-34:00] - Delegating tasks to autonomous agents reduces individual agency over automated decisions.','Review Human Agency.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q4',9,'Privacy-preserving Training','assignment','medium','multi','Which of the following are privacy-preserving training techniques? (Select all that apply.)','["Model Quantization", "Differential Privacy", "Federated Learning", "Data Augmentation"]'::jsonb,'[1, 2]'::jsonb,NULL,0.0,'Differential Privacy protects individual data by adding carefully calibrated noise during training while maintaining useful model performance. Federated Learning trains models across decentralized devices without requiring the personal data to be centrally collected.','Review Privacy-preserving Training.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q5',9,'Co-regulation','assignment','medium','single','In structured AI governance, what is defines a “co-regulation” model from from strict-regulation or self-regulation?','["Companies operate without zero external guidelines or government interaction.", "The government directly dictates every policy of code without interference from the industry.", "The government ensures that consumers have as much responsiblities as companies to follow policy.", "Industries establish policies which are formally recognized and enforced by the government."]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 2 [49:10-51:06] - Co-regulation combines industry expertise in defining baseline standards with government authorization to enforce them across the industry.','Review Co-regulation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q6',9,'Copyright Unlearning','assignment','medium','single','According to the lecture, if copyrighted data is found inside a large AI model and must be removed, what is a major technical challenge?','["Removing the data may significantly reduce the model’s ability to generalize to unrelated tasks.", "The model may need to be retrained or use specialized unlearning techniques to remove the data’s influence.", "The model may become unstable because removing one data point automatically changes its entire architecture.", "The model may require additional training on the copyrighted data before its influence can be safely removed."]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 2 [45:45-47:05] - Purging individual data points from large AI models is complex and often requires costly model retraining or complex unlearning algorithms.','Review Copyright Unlearning.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q7',9,'Safety Budget','assignment','medium','single','According to the discussed AI safety and governance proposals, about how much of an AI model’s development budget should be spent on safety and responsible AI?','["50% on legal costs", "100% on testing the model after it is released", "10% on AI safety and responsible AI research", "All profits on building newer hardware"]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 3 [5:35-6:11] - Tristan Harris proposed allocating 10% of model development budgets to safe and responsible AI practices.','Review Safety Budget.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q8',9,'Energy Strategy','assignment','medium','single','According to the lecture, which technical strategy help reduce the energy consumption and environmental footprint of LLM deployment?','["Routing every simple text query to ultra-large GPU clusters in real time.", "Increasing parameter counts by 10x for routine classification tasks.", "Running duplicate backup models continuously on solar-powered data centers.", "Moving model inference to run on CPUs/Edge devices instead of GPUs."]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 3 [18:40-20:26] - Running models on CPU/Edge devices makes infrastructure cheaper and environmentally friendly as they require less energy.','Review Energy Strategy.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q9',9,'Back Translation Defense','assignment','medium','single','How does Back Translation Defense mitigate jailbreak attacks?','["It takes an unmoderated model output, reverse-infers the prompt that generated it, and runs it through safety filters.", "It translates outputs into multiple foreign languages until a syntax error occurs.", "It automatically rejects any prompt containing more words than the model’s maximum context window.", "It re-encrypts the LLM’s weights after every user interaction."]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Policies, Regulations, AGI - Part 3 [23:22-25:02] - Back-translation reconstructs the user prompt from the generated output so moderation filters can catch hidden jailbreak attempts.','Review Back Translation Defense.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q10',9,'RAI Principles','assignment','medium','multi','Which of the following are principles of Responsible AI (RAI)? (Select all that apply.)','["Fairness", "Explainability", "AI Autonomy", "Accountability", "Fast Deployment", "Privacy"]'::jsonb,'[0, 1, 3, 5]'::jsonb,NULL,0.0,'Week 9 Lec 45 Lecture Notes [Slide 5] - Fairness, Explainability, Accountability and Privacy are RAI Principles.','Review RAI Principles.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q11',9,'Fairness Tree','assignment','medium','single','According to the Fairness Tree Framework, which fairness metric is recommended when interventions are punitive and you are most concerned with ensuring predictive equity among people for whom intervention is taken?','["FN/GS Parity", "FP/GS Pairty", "FDR Parity", "FPR Parity"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Week 9 Lec 45 Lecture Notes [Slide 20] - FDR Parity is used when intervention is punitive (could hurt individuals) and you are most concerned with ensuring predictive equity among people for whom intervention is taken?','Review Fairness Tree.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w9_q12',9,'Systems Approach','assignment','medium','single','According to the systems approach framework for AI design and development, what action immediately follows the step of analyzing the root causes of bias?','["Measure and detect the bias", "Mitigate the impact through adjusting interventions", "Monitor & Evaluate", "Improve fairness of AI systems"]'::jsonb,'[3]'::jsonb,NULL,0.0,'Week 9 Lec 45 Lecture Notes [Slide 16] - Analyzing the root causes occurs in the Understand step, and the next is the Improve step.','Review Systems Approach.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q1',10,'Black-box Auditing','assignment','medium','single','According to the lecture, why is black-box access considered insufficient for conducting rigorous AI auditing?','["It restricts evaluation to only the utilization of computation.", "It focuses only on the final outputs rather than the internal mechanisms.", "It fails to reveal underlying problematic model behaviour.", "It requires the auditors to retrain the underlying weights from scratch."]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [3:56-4:31] - Black-box auditing is insufficient because the auditor might fail to identify and surface the model’s problematic behaviour.','Review Black-box Auditing.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q2',10,'Goal Misgeneralization','assignment','medium','single','How does “goal misgeneralization” differ from “reward hacking”?','["The agent pursues a different goal that is merely correlated with the true reward function.", "The agent continuously optimizes an imperfect proxy goal, worsening the outcomes.", "The agent actively manipulates its own code to rewrite the target goal.", "The agent randomly pursues a completely new, unpredictable behvaiour is deployment."]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [6:22-7:07] - Goal misgeneralization is when the model ends up optimizing a different reward function because it was merely correlated with the true reward function.','Review Goal Misgeneralization.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q3',10,'Agentic AI','assignment','medium','single','Which of the following characteristics of highly agentic AI systems could introduce severe safety concerns beyond those of current language models?','["High parameter count and dense multi-head attention.", "Increased speed of token generation in text.", "Exploding context window expansion.", "Direct interaction with external digital infrastructure."]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [32:10-33:53] - According to the lecture, highly agentic systems present severe existential and safety risks. When AI systems are plugged into digital infrastructures, companies, militaries, etc., and allowed to act autonomously, they may be able to successfully “disempower humanity”.','Review Agentic AI.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q4',10,'Benchmark Limits','assignment','medium','single','Why are benchmarks insufficient for assessing dangerous capabilities in current models?','["Benchmarks fail to capture emergent behaviours in a tool-based environment.", "Benchmarks require white-box parameter access to accurately test models.", "Benchmarks are only able to accurately assess image models and not language models.", "Benchmarks cannot measure basic mathematical computation accuracy."]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [23:07-23:41] - Benchmarks don’t reflect underlying capability because they can be very narrow. Looking at performance on a slightly different distribution shows that a system can perform much differently.','Review Benchmark Limits.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q5',10,'Positive Case','assignment','medium','single','Instead of relying on third-party audits, what alternative approach can developers use to demonstrate that a model is safe before deployment?','["Deploying models in restricted sandbox environments to observe failure cases.", "Releasing the complete source code and model weights to the public.", "Providing a positive case demonstrating that the system is safe.", "Mandating that all training be physically monitored by the public."]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [7:16-7:50] - Developers should be making a positive deployment of AI systems to show that they are safe and that they are going to have a positive impact.','Review Positive Case.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q6',10,'Personalized Assistants','assignment','medium','single','What is a systemic risk about highly capable, personalized AI assistants that adapt to a user''s habits?','["They will overwrite local user data to optimize their performance.", "They will frequently hallucinate and fabricate sensitive personal information or memories.", "They put dangerous amounts of private information in the hands of a few big companies.", "They require localized hardware upgrades that need to be funded by the user."]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [40:20-41:28] - By having these AI assistants learn about very personal information, this information is being stored by big companies, which gives them a dangerous amount of power.','Review Personalized Assistants.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q7',10,'Copyright Fair Use','assignment','medium','single','According to the lecture, why is training models on copyrighted data not constitute “transformative fair use”?','["The models fail to provide accurate citations for the generated content.", "The resulting model directly competes economically with the creators.", "The generated outputs are legally indistinguishable from the copyrighted data.", "The training process stores exact copies of the original works."]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [36:46-37:48] - The models are directly competing with the creators of the copyrighted data, which does not fall under fair use.','Review Copyright Fair Use.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q8',10,'Single-country Regulation','assignment','medium','single','According to the lecture, why might single-nation AI regulations fail to prevent the deployment of dangerous AI systems?','["National regulators lack the technical tools needed to monitor large computing data centers within their own borders.", "Individual nations may have the need to bypass regulations and build dangerous AI systems anyways.", "International copyright laws prevent individual countries from enforcing safety standards on foreign models.", "Private AI companies can legally overturn single-nation safety laws in international judicial systems."]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 1 [31:03-31:19] - Individual nations may have reasons to bypass regulations and build a “dangerous” AI.','Review Single-country Regulation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q9',10,'Superficial Alignment','assignment','medium','single','Which mechanism explains why safety fine-tuning may fail to eliminate deep-seated societal biases in LLMs?','["Catastrophic learning episodes", "Superficial behaviour alignment", "Inference latency optimization", "Data scaling bottlenecks"]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 2 [2:00-3:55] - Safety mechanisms or safety fine-tuning in LLMs are often superficial. They teach systems to say a "politically correct" answer, while deep-seated implicit biases remain hidden in the model''s underlying representations.','Review Superficial Alignment.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q10',10,'Persuasiveness','assignment','medium','single','Why is it dangerous for AI systems to be optimized for user persuasiveness?','["It requires continuous access to quantum compute.", "It degrades latency during multi-turn dialogue.", "It creates incentives to manipulate human intent.", "It prevents models from processing implicit or indirect input cues"]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 2 [27:19-28:08] - Optimizing persuasiveness gives AI systems leverage to manipulate human behaviour and intention, essentially using human beings as a means to an end.','Review Persuasiveness.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q11',10,'Upstream Regulation','assignment','medium','single','Why is it better to have upstream regulation for companies developing AI systems and hardware than having downstream regulation on the people using the AI systems?','["Developers are completely free of standard regulations.", "Developers lack any technical control over baseline models.", "Users control the underlying training data pipeline.", "Users face high market pressure to adopt AI systems."]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 2 [7:03-7:37] - AI systems provide users with a competitive advantage, and they feel immense pressure to adopt AI in order for their business to survive.','Review Upstream Regulation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w10_q12',10,'Cross-modal AGI','assignment','medium','single','According to the lecture, why is cross-modal capability considered to be a characteristic of Artificial General Intelligence (AGI)?','["Text processing requires higher computational memory.", "Multimodal models eliminate risks of hallucinations in the outputs.", "Language models cannot represent abstract reasoning.", "Excluding human modalities creates a gap in real-world understanding."]'::jsonb,'[3]'::jsonb,NULL,0.0,'AI Policies, AGI with Prof. David Krueger - Part 2 [13:18-13:37] - Multimodality is a crucial component for AGI, as without it, it creates a qualitative cognitive deficit.','Review Cross-modal AGI.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q1',11,'Right to be Forgotten','assignment','medium','single','In the context of data privacy, which right requires companies to delete user data when requested?','["Right to intellectual property retention", "Right to be forgotten", "Right to data portability", "Right to transparency"]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Governance [9:56-11:50] - The right to be forgotten (or the right to erasure) gives the data subject the right to erasure of their personal data.','Review Right to be Forgotten.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q2',11,'OECD Safety','assignment','medium','single','Which OECD AI Principle states that AI systems should operate safely and function properly under normal use, misuse, or adverse conditions?','["Inclusive growth, sustainable development and well-being", "Transparency and explainability", "Robustness, security, and safety", "Accountability"]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Governance [18:12-19:00] - Robustness, Security, and Safety states that AI systems should be robust, secure, and safe throughout their entire lifecycle.','Review OECD Safety.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q3',11,'EU AI Act','assignment','medium','multi','Under the EU AI Act, which application category is classified as an ''unacceptable risk''? (Select all that apply.)','["Social Scoring Systems", "Critical Infrastructure Management", "Law Enforcement", "Cognitive Behavioural Manipulation"]'::jsonb,'[0, 3]'::jsonb,NULL,0.0,'AI Governance [25:22-26:56] - According to the EU AI Act, social scoring and cognitive behavioural manipulation are unacceptable risks.','Review EU AI Act.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q4',11,'Silent Threat Elimination','assignment','medium','single','When a system like an email spam server filters out malicious messages in the background without requiring user intervention, which type of threat mitigation is it demonstrating?','["Educating and training users", "Providing interface-level threat warnings", "Silently eliminating the threat", "Enforcing legal regulations"]'::jsonb,'[2]'::jsonb,NULL,0.0,'AI Governance [4:41-8:17] - Spam servers operate behind the scenes to remove unwanted or dangerous emails automatically.','Review Silent Threat Elimination.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q5',11,'Deepfake Labelling','assignment','medium','single','What specific transparency requirement does the EU AI Act impose on deepfakes or generated media?','["They must be exclusively hosted on European-based servers.", "They must be clearly labeled as AI-generated.", "They must not be published on the internet at all.", "They must be heavily taxed before distribution."]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Governance [28:00-29:35] - The act mandates that any images, audio, or video files generated or modified by AI must be explicitly labeled.','Review Deepfake Labelling.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q6',11,'Deployer','assignment','medium','single','In the AI Value Chain, who is considered the "deployer"?','["The person or organization that uses the AI systems under its own authority.", "The original engineering team that built the AI model.", "The individual who imports the AI system into the EU market.", "The government official responsible for writing the regulations."]'::jsonb,'[0]'::jsonb,NULL,0.0,'AI Governance [30:12-31:55]: The deployer is the persons that use AI systems under their authority.','Review Deployer.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q7',11,'Traceability','assignment','medium','single','To satisfy the OECD principle of "accountability," AI actors should ensure "traceability" throughout the system''s lifecycle. What does this specifically help achieve?','["It allows companies to track user information that can lead to their location, such as IP addresses.", "It ensures one can trace back how data was collected and how it influences decision-making.", "It guarantees the system uses minimal computing power and has a low carbon footprint.", "It allows the AI to completely wipe its training period after a set period."]'::jsonb,'[1]'::jsonb,NULL,0.0,'AI Governance [19:02-19:53]: Traceability ensures that if an AI makes a particular choice, auditors can trace the datasets and processes that led to that specific outcome.','Review Traceability.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q8',11,'SaGE Semantic Inconsistency','assignment','medium','single','In the SaGE framework, how is semantic inconsistency functionally defined?','["Failing to identify commonsense reasoning violations within a single prompt.", "Generating factually incorrect statements in response to a factual prompt.", "Utilizing grammatically disparate structures to answer identical prompts.", "Providing semantically disparate answers to semantically equivalent prompts."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Research Overview: SaGE- Quantifying moral consistency in LLMs [2:27-2:52] - Semantic inconsistency is an LLM generating contradictory or different answers when presented with semantically equivalent prompts.','Review SaGE Semantic Inconsistency.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q9',11,'SaGE Entropy','assignment','medium','single','In the SaGE framework, what does a higher semantic graph entropy indicate about the LLM?','["The model is exhibiting higher semantic consistency.", "The model is exhibiting higher semantic inconsistency.", "The model is exhibiting lower syntactic divergence.", "The model is exhibiting lower fundamental judgment."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Research Overview: SaGE- Quantifying moral consistency in LLMs [15:32-18:43]: Higher graph entropy indicates greater randomness among the generated responses, which means the model''s answers are inconsistent.','Review SaGE Entropy.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q10',11,'SaGE Temperature','assignment','medium','single','A developer attempts to reduce an LLM''s tendency to give contradictory answers to moral questions by lowering the generation temperature. Based on SaGE, what is the expected outcome?','["The consistency score will improve to near perfection.", "The consistency score will perfectly match human scores.", "The consistency score will drop to near zero.", "The consistency score will remain largely unaffected."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Research Overview: SaGE- Quantifying moral consistency in LLMs [21:52-22:44]: The SaGE study demonstrated that changing the temperature does not significantly alter the model’s consistency.','Review SaGE Temperature.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w11_q11',11,'SaGE Benchmark Correlation','assignment','medium','single','According to the SaGE framework, how does an LLM''s accuracy on standard commonsense reasoning benchmarks correlate with its moral consistency?','["Accuracy negatively correlates with consistency.", "Accuracy does not correlate with consistency.", "Accuracy strictly correlates with consistency.", "Accuracy conditionally correlates with consistency."]'::jsonb,'[1]'::jsonb,NULL,0.0,'Research Overview: SaGE- Quantifying moral consistency in LLMs [22:45-23:58]: The SaGE study demonstrated that a model''s benchmark accuracy does not correlate with its consistency at all.','Review SaGE Benchmark Correlation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q1',12,'Guarded Attribute','assignment','medium','single','What does a ‘guarded’ attribute mean in a language model’s representation space?','["The attribute can only be classified by specific linear probes.", "The attribute requires non-linear transformations to be classified.", "The attribute is heavily emphasized during the initial pre-training process.", "The attribute is entirely impossible to classify based on the representation."]'::jsonb,'[3]'::jsonb,NULL,0.0,'An attribute Z is considered guarded if we can''t classify along that attribute.','Review Guarded Attribute.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q2',12,'Representation Guarding','assignment','medium','single','What is the primary objective of modifying vectors from one distribution (e.g., toxic to non-toxic) to look like another?','["To increase the computational cost of generating toxic content.", "To guard an attribute with the smallest possible change to unrelated semantics.", "To fundamentally alter the underlying vocabulary of the model.", "To completely randomize the vector outputs of specific trigger tokens."]'::jsonb,'[1]'::jsonb,NULL,0.0,'We want to guard an attribute with the smallest change possible to preserve semantics unrelated to Z.','Review Representation Guarding.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q3',12,'Affine Steering','assignment','medium','single','According to the lecture, what is the implication behind using Affine Steering?','["It is a no-gradient and cheap way to control model generation.", "It fine-tunes the model to effectively remove bias using minimal training data.", "It is a highly interpretable, gradient-based optimization method.", "It depends heavily on reinforcement learning and human feedback."]'::jsonb,'[0]'::jsonb,NULL,0.0,'Affine Steering is a no-gradient and cheap way to control generation and to de-bias.','Review Affine Steering.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q4',12,'Cell Complex Scaling','assignment','medium','single','How does the size of a conventional cell complex scale as the size of the graph increases?','["It scales inversely with respect to graph size.", "It scales quadratically with respect to graph size.", "It scales logarithmically with respect to graph size.", "It scales linearly with respect to graph size."]'::jsonb,'[1]'::jsonb,NULL,0.0,'The size of a conventional cell complex will scale quadratically as the size of the graph increases.','Review Cell Complex Scaling.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q5',12,'Graph Explainers','assignment','medium','single','In the molecule toxicity detection task, why might a standard Graph Neural Network Explainer fail to identify the correct explanation?','["It removes all nodes that have a high edge degree.", "It processes node features too slowly for a chemical dataset.", "It cannot capture specific multi-node groupwise interactions.", "It assigns zero weight to all the chemical bonds by default."]'::jsonb,'[2]'::jsonb,NULL,0.0,'A limitation of graphs is that they can only model pairwise relationships between nodes.','Review Graph Explainers.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q6',12,'FORGE','assignment','medium','single','How does FORGE reduce the computational complexity of the cell complex to a linear scale?','["By randomly sampling only 10% of the original graph edges.", "By strategically removing specific types of boundary relations.", "By completely deleting all nodes with a degree higher than a threshold degree.", "By executing the explainer algorithm on highly compressed latent space."]'::jsonb,'[1]'::jsonb,NULL,0.0,'By strategically removing specific types of boundary relations, we can bring this down to linear complexity.','Review FORGE.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q7',12,'Cycles','assignment','medium','single','How are cycles structurally represented in the cell complex?','["They are represented as 0-cells.", "They are represented as 1-cells.", "They are represented as 2-cells.", "They are represented as 3-cells."]'::jsonb,'[2]'::jsonb,NULL,0.0,'Cycles are 2-cells, which are represented as augmented nodes connected to all edges that make up that cycle.','Review Cycles.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q8',12,'Graph Explainer Applications','assignment','medium','multi','Which of the following are examples of graph explainers? (Select all that apply.)','["Predicting the next token in a language model", "Toxicity detection of molecules", "Affine concept erasure", "Drug prediction", "Fraud detection"]'::jsonb,'[1, 3, 4]'::jsonb,NULL,0.0,'Graph explainers are important in toxicity detection of molecules, drug prediction, fraud detection, etc.','Review Graph Explainer Applications.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q9',12,'FORGE Benefits','assignment','medium','single','Which of the following methods benefits the most from the FORGE framework?','["Attention-based methods", "Surrogate-based methods", "Gradient-based methods", "Perturbation-based methods Explanation: Perturbation-based methods benefit the most from FORGE."]'::jsonb,'[3]'::jsonb,NULL,0.0,'Perturbation-based methods benefit the most from FORGE.','Review FORGE Benefits.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('assignment_w12_q10',12,'Cell Complex Definitions','assignment','medium','multi','Based on the mathematical definitions of cell complexes presented in the FORGE slides, which of the following statements are correct? (Select all that apply.)','["A 0-cell corresponds to a vertex, while a 1-cell corresponds to an edge in traditional graphs. (1)", "The 1-skeleton 𝑋 of a cell complex consists exclusively of 1-dimensional cells.", "Vertical boundary relations connect two cells of the same dimension that share a common boundary.", "Boundary relations in the framework are restricted to be undirected, meaning σ𝑐 ,𝑐 = σ𝑐 ,𝑐 . 1 2 2 1 (𝑝) (𝑝+1)", "A 𝑝-cell 𝑐 is considered a face or boundary of a (𝑝 + 1)-cell 𝑐 if the set of (𝑝) (𝑝+1) points composing 𝑐 is a subset of those composing 𝑐 . Explanation: A - Definition 3.1 (𝑝) B - Definition 3.4 states that 𝑋 is a subcomplex of cells of dimension at most 𝑝, meaning both 0- and 1-cells. C - Definition 3.5 states horizontal boundary relations as linking two 𝑝-cells of the same dimension, whereas vertical boundary relations link cells of different dimensions. D - Definition 3.5 E - Definition 3.2"]'::jsonb,'[0, 3, 4]'::jsonb,NULL,0.0,'A - Definition 3.1 (𝑝) B - Definition 3.4 states that 𝑋 is a subcomplex of cells of dimension at most 𝑝, meaning both 0- and 1-cells. C - Definition 3.5 states horizontal boundary relations as linking two 𝑝-cells of the same dimension, whereas vertical boundary relations link cells of different dimensions. D - Definition 3.5 E - Definition 3.2','Review Cell Complex Definitions.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w1q6',1,'Risk Equation','new','medium','multi','Which mappings correctly reduce components of the disaster-risk equation? Select all that apply.','["Vulnerability → robustness", "Exposure → monitoring", "Hazard → alignment", "Exposure → parameter scaling"]'::jsonb,'[0, 1, 2]'::jsonb,NULL,0.0,'The course maps vulnerability to robustness, exposure to monitoring, and hazard to alignment.','V-R, E-M, H-A.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w1q7',1,'Treacherous Turn','new','hard','single','A system follows instructions until it becomes capable of bypassing oversight, then changes behavior. Which term fits best?','["Treacherous turn", "Deceptive alignment", "Eroded epistemics", "Enfeeblement"]'::jsonb,'[0]'::jsonb,NULL,0.0,'A treacherous turn is the later behavior change once capability or opportunity makes defection possible.','Treacherous = changes later.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w2q6',2,'RLHF','new','medium','single','Which sequence best matches the RLHF pipeline taught in the course?','["Demonstrations → comparisons → reward model → policy improvement", "Reward model → demonstrations → deployment → comparisons", "Comparisons → policy deletion → demonstrations → retraining", "Pretraining → encryption → reward model → quantization"]'::jsonb,'[0]'::jsonb,NULL,0.0,'The course flow is demonstrations, preference comparisons, reward-model training, then policy improvement.','RLHF: demos → comparisons → reward → improve.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w2q7',2,'DPO and KL','new','hard','single','What is the role of a KL penalty during preference-based policy improvement?','["Keep the updated policy from drifting too far from the original", "Force every reward-model score to equal one", "Increase the number of human preference labels", "Remove all uncertainty from model outputs"]'::jsonb,'[0]'::jsonb,NULL,0.0,'A KL penalty discourages excessive divergence from the reference or pretrained policy.','KL penalty = stay close to the original policy.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w3q6',3,'Exact vs Approximate Unlearning','new','hard','single','Which statement correctly distinguishes exact from approximate unlearning?','["Exact matches retraining distributionally; approximate is only close", "Exact is only for graphs; approximate is only for language models", "Exact keeps all forgotten data; approximate deletes the dataset", "Exact always uses DP; approximate never uses probability bounds"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Exact unlearning should be distributionally indistinguishable from retraining without the removed data; approximate unlearning only needs closeness.','Exact = identical; approximate = close.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w3q7',3,'Representation Engineering','new','medium','single','What does representation engineering do?','["Modify internal representation vectors to influence model behavior", "Increase model parameters by duplicating hidden layers", "Relabel every example in the training set", "Measure only output probabilities without intervention"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Representation engineering changes internal vectors or directions to control traits or outputs.','Representation engineering = modify internal vectors.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w4q6',4,'Reporting Bias','new','medium','single','What is reporting bias?','["Some kinds of events are overrepresented because people are more likely to report them", "A model reports every prediction with the same confidence", "A dataset has equal numbers from every group", "Annotators intentionally change labels after deployment"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Reporting bias arises when what gets recorded differs systematically from what actually occurs.','Reporting bias = what gets reported is not what happens equally.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w4q7',4,'Fair PCA','new','hard','single','At the fairness objective discussed for Fair PCA, how should reconstruction losses compare across groups?','["They should be equalized across the groups", "The protected group should always have lower loss", "The unprotected group should always have lower loss", "Loss should be ignored if variance is high"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Fair PCA seeks a solution that equalizes group reconstruction losses at the fairness optimum.','Fair PCA = equal reconstruction loss.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w5q6',5,'PMI','new','hard','single','If P(i,j)/(P(i)P(j)) = 4, what is PMI using log base 2?','["2", "4", "8", "16"]'::jsonb,'[0]'::jsonb,NULL,0.0,'PMI = log2(4) = 2.','PMI = log2 of the probability ratio.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w5q7',5,'Catastrophic Forgetting','new','medium','single','Why can full-parameter debiasing cause catastrophic forgetting?','["Changing all weights can damage performance on unrelated tasks", "Debiasing always doubles the number of model layers", "Bias metrics require deleting the training set", "The model must stop using every protected attribute"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Aggressive fine-tuning across all parameters can overwrite useful knowledge and reduce general capability.','Catastrophic forgetting = fix one thing, lose other learned ability.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w6q6',6,'DP Bound','new','hard','single','In ε-differential privacy, what bounds the ratio of output probabilities on neighboring datasets?','["e^ε", "ε²", "1/ε", "log ε"]'::jsonb,'[0]'::jsonb,NULL,0.0,'The defining multiplicative bound is e^ε.','DP probability ratio ≤ e^ε.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w6q7',6,'Laplace Noise','new','medium','single','With epsilon fixed, what happens to Laplace noise when query sensitivity increases?','["More noise is required", "Less noise is required", "Noise stays unchanged", "Noise is replaced by quantization"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Laplace scale is proportional to sensitivity for a fixed privacy budget.','Sensitivity up → noise up.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w7q6',7,'COMPAS Fairness','new','hard','multi','Which patterns were highlighted in the COMPAS fairness example? Select all that apply.','["African American defendants had more false high-risk labels", "White defendants had more false low-risk labels", "Both groups had identical error types", "African American defendants had fewer false low-risk labels than White defendants"]'::jsonb,'[0, 1, 3]'::jsonb,NULL,0.0,'The lecture emphasizes asymmetric false-positive and false-negative patterns across groups.','COMPAS: AA false-high more; White false-low more.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w7q7',7,'Fair PCA','new','medium','single','What fairness goal does Fair PCA use for group reconstruction errors?','["Equalize group reconstruction losses", "Maximize loss for the protected group", "Ignore group-specific reconstruction loss", "Use different feature dimensions for each group"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Fair PCA seeks equal reconstruction losses across groups under the discussed formulation.','Fair PCA = equal group losses.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w8q6',8,'Top-down vs Mechanistic','new','hard','single','Which distinction between top-down and mechanistic interpretability is correct?','["Top-down asks where information is represented; mechanistic asks how the internal computation works", "Top-down is only for images; mechanistic is only for text", "Top-down requires source code; mechanistic requires only outputs", "Top-down measures fairness; mechanistic measures privacy"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Top-down approaches localize representations; mechanistic interpretability attempts to reverse-engineer internal mechanisms.','Top-down = where; mechanistic = how.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
