insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w9q6',9,'Back Translation Defense','new','medium','single','How does Back Translation Defense help detect jailbreaks?','["Infer a likely prompt from the output and pass it through safety checks", "Translate the answer into many languages until it changes", "Reject every prompt above a fixed word count", "Encrypt the model weights after each response"]'::jsonb,'[0]'::jsonb,NULL,0.0,'The defense reconstructs a prompt from an unmoderated output so moderation can catch hidden jailbreak intent.','Output → reconstruct prompt → safety filter.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w9q7',9,'Fairness Tree','new','hard','single','For a punitive intervention, which fairness metric does the course recommend when focusing on people who receive the intervention?','["FDR parity", "FPR parity", "Statistical-parity difference", "Equal reconstruction loss"]'::jsonb,'[0]'::jsonb,NULL,0.0,'The Fairness Tree uses FDR parity for punitive interventions when predictive equity among selected individuals matters.','Punitive intervention → FDR parity.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w10q6',10,'Superficial Alignment','new','hard','single','What does superficial behavior alignment mean?','["The model learns safe-looking responses while deeper biases can remain", "The model becomes unbiased at every internal layer", "The model removes all unsafe data before training", "The model refuses every controversial question"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Safety fine-tuning can change visible responses without fully removing underlying biased representations.','Looks safe outside; bias may remain inside.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w10q7',10,'Persuasiveness','new','medium','single','Why can optimizing an AI system for persuasiveness create safety concerns?','["It can reward strategies that manipulate human intentions", "It guarantees slower response generation", "It prevents the model from understanding indirect language", "It removes the need for user consent"]'::jsonb,'[0]'::jsonb,NULL,0.0,'A system rewarded for persuasion may learn to manipulate people as a means to its objective.','Persuasiveness optimization can incentivize manipulation.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w11q6',11,'SaGE Entropy','new','hard','single','What does higher semantic graph entropy indicate in SaGE?','["Greater semantic inconsistency", "Greater semantic consistency", "Lower model temperature", "Higher benchmark accuracy"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Higher graph entropy means responses are more varied or random, corresponding to more inconsistency.','Higher entropy = more inconsistency.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w11q7',11,'SaGE Temperature','new','medium','single','What did SaGE find about lowering generation temperature to fix moral inconsistency?','["Consistency stayed largely unchanged", "Consistency became nearly perfect", "Consistency always dropped to zero", "Consistency matched human judgments exactly"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Changing temperature did not significantly alter moral consistency in the reported study.','Lower temperature ≠ consistency fix.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w12q6',12,'Cycles','new','easy','single','How is a cycle represented in the cell complex used in the course?','["As a 2-cell", "As a 0-cell", "As a 1-cell", "As a 3-cell"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Cycles are represented as 2-cells connected to the edges that form the cycle.','Vertex 0, edge 1, cycle 2.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_adapted_w12q7',12,'Graph Explainers','new','hard','single','Why can a standard graph explainer miss the correct explanation for molecular toxicity?','["Pairwise graph relations may miss multi-node group interactions", "Graphs cannot store chemical node features", "Every graph explainer assigns zero weight to bonds", "Toxicity can only be explained with language models"]'::jsonb,'[0]'::jsonb,NULL,0.0,'Ordinary graphs model pairwise relationships and may fail to capture higher-order interactions among multiple nodes.','Pairwise graph may miss group interaction.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_num_1',5,'PMI','new','medium','single','In a dataset of 1000 records, A appears 100 times, B appears 50 times, and both appear 20 times. What is PMI(A,B) using log base 2?','["0", "1", "2", "4"]'::jsonb,'[2]'::jsonb,NULL,0.0,'P(A,B)=0.02 and P(A)P(B)=0.005. The ratio is 4, so log2(4)=2.','P(A,B)=0.02 and P(A)P(B)=0.005. The ratio is 4, so log2(4)=2.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_num_2',7,'Revenue calculation','new','medium','single','Three buyers value an item at 15, 20, and 135. What is the absolute revenue difference between prices 14 and 18?','["4", "6", "8", "10"]'::jsonb,'[1]'::jsonb,NULL,0.0,'Price 14 sells to 3 buyers: 42. Price 18 sells to 2: 36. Difference = 6.','Price 14 sells to 3 buyers: 42. Price 18 sells to 2: 36. Difference = 6.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_num_3',7,'DP composition','new','medium','single','Three independent mechanisms each provide (1, 0.001)-differential privacy. Under basic composition, what is the combined guarantee?','["(1, 0.003)", "(3, 0.001)", "(3, 0.003)", "(0.33, 0.003)"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Basic composition adds epsilon and delta: (3, 0.003).','Basic composition adds epsilon and delta: (3, 0.003).') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_num_4',7,'Statistical parity','new','medium','single','Group A has a positive decision rate of 60% and group B has 45%. What is the absolute statistical-parity difference?','["5 percentage points", "10 percentage points", "15 percentage points", "25 percentage points"]'::jsonb,'[2]'::jsonb,NULL,0.0,'Subtract the positive rates: |0.60 - 0.45| = 0.15.','Subtract the positive rates: |0.60 - 0.45| = 0.15.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
