insert into public.questions (id,week,topic,source,difficulty,type,question_text,options,correct_answers,numeric_answer,tolerance,explanation,memory_tip) values ('extra_extra_num_6',7,'Revenue calculation','new','medium','single','Buyer valuations are 10, 30 and 50. Compare revenues at prices 10 and 20. What is the absolute difference?','["0", "5", "10", "20"]'::jsonb,'[2]'::jsonb,NULL,0.0,'At 10 revenue = 3×10=30; at 20 revenue = 2×20=40. Difference = 10.','At 10 revenue = 3×10=30; at 20 revenue = 2×20=40. Difference = 10.') on conflict (id) do update set week=excluded.week, topic=excluded.topic, source=excluded.source, difficulty=excluded.difficulty, type=excluded.type, question_text=excluded.question_text, options=excluded.options, correct_answers=excluded.correct_answers, numeric_answer=excluded.numeric_answer, tolerance=excluded.tolerance, explanation=excluded.explanation, memory_tip=excluded.memory_tip;
